package io.github.ningpp.compat;

/**
 * Replacement for System.Text.Encodings.Web.UnicodeRange (generated by CSharpToJava converter).
 */
public final class UnicodeRange {
    private final int firstCodePoint;
    private final int length;

    public UnicodeRange(int firstCodePoint, int length) {
        this.firstCodePoint = firstCodePoint;
        this.length = length;
    }

    /** Mirrors UnicodeRange.Create(firstChar, lastChar) — inclusive character range. */
    public static UnicodeRange create(char firstChar, char lastChar) {
        return new UnicodeRange(firstChar, lastChar - firstChar + 1);
    }

    public int getFirstCodePoint() {
        return firstCodePoint;
    }

    public int getLength() {
        return length;
    }

    public boolean contains(int codePoint) {
        return codePoint >= firstCodePoint && codePoint < firstCodePoint + length;
    }
}
